namespace Taruck.CharacterCreation
{
    internal static class CharacterMonkSpellText
    {
        internal static string Effect(RulesEdition edition, string name)
        {
            bool modern = edition == RulesEdition.Rules2024;
            switch (name)
            {
                case "Beast Sense": return modern ? "Дотик до охочого звіра: сприймай через його чуття разом зі своїми, включно з особливими чуттями звіра." : "Дотик до охочого звіра: дією бачиш його очима й чуєш його вухами, отримуєш його особливі чуття; власні зір і слух недоступні. Дією поверни власні чуття.";
                case "Commune with Nature": return modern ? "Дізнайся три відомості про місцевість у радіусі 3 миль або 300 футів у природних печерах: поселення, портали, одну небесну, стихійну, фейську, демонічну чи неживу істоту рівня небезпеки 10+ на вибір майстра, найпоширеніші рослини, мінерали чи звірів, або водойми. Не діє у забудованих зонах." : "Отримай до трьох відомостей про місцевість у радіусі 3 миль над землею або 300 футів у природних печерах: ландшафт, рослини, вода, істоти, вплив інших планів чи споруди. Не діє у забудованих зонах на кшталт міст і підземель.";
                case "Darkness": return "Магічна темрява у сфері радіусом 15 футів огинає кути; звичайний темнозір і немагічне світло не допомагають. Джерелом може бути предмет; непрозоре накриття блокує темряву. Розсіює світло спелів 2 круга або нижче при перекритті зон.";
                case "Darkvision": return modern ? "Охоча істота отримує темнозір на 150 футів." : "Охоча істота отримує темнозір на 60 футів.";
                case "Pass without Trace": return modern
                    ? "Ти й обрані істоти в аурі 30 футів отримуєте +10 до Скритності й не залишаєте слідів."
                    : "Обрані істоти в 30 футах, включно з тобою, отримують +10 до Скритності й не залишають слідів; вистежити їх можна лише магією.";
                case "Silence": return "У сфері радіусом 20 футів немає звуку; повністю всередині — імунітет до громової шкоди й стан Оглухлий. Не можна накладати спели з вербальними компонентами.";
                case "Astral Projection": return "Душа залишає нерухоме тіло й подорожує Астральною площиною, з’єднана срібною ниткою. Повернення завершує проєкцію; розрив нитки вбиває. Тіло не потребує їжі, повітря та не старіє; проєкція має окрему копію статистики й спорядження.";
                case "Cone of Cold": return "Конус 60 футів: ряткидок Статури проти 8к8 холодної шкоди, успіх — половина. Убита цим спелом істота стає замерзлою статуєю, доки не розтане.";
                case "Hold Person": return "Видимий гуманоїд: ряткидок Мудрості або Паралізований; повторює ряткидок наприкінці кожного свого ходу, успіх завершує ефект.";
                case "Stoneskin": return modern ? "Охоча істота отримує опір дробильній, колючій і рубаній шкоді, включно з магічною." : "Охоча істота отримує опір немагічній дробильній, колючій і рубаній шкоді.";
                case "Fireball": return "Сфера радіусом 20 футів: Спритність проти 8к6 вогняної шкоди, успіх — половина. Вогонь огинає кути й запалює незайняті горючі предмети.";
                case "Shatter": return modern
                    ? "Сфера радіусом 10 футів: Статура проти 3к8 громової шкоди, успіх — половина. Конструкти мають заваду; немагічні незайняті предмети теж отримують шкоду."
                    : "Сфера радіусом 10 футів: Статура проти 3к8 громової шкоди, успіх — половина. Істоти з каменю, кристалу чи металу мають заваду; немагічні незайняті предмети теж отримують шкоду.";
                case "Gaseous Form": return "Охоча істота та її речі стають хмарою: політ 10 футів, прохід крізь щілини, опір немагічній шкоді й перевага ряткидків Сили, Спритності та Статури. Не може атакувати, накладати спели чи маніпулювати предметами; не падає.";
                case "Fly": return "Охоча істота отримує швидкість польоту 60 футів; після завершення може впасти, якщо не здатна зупинити падіння.";
                case "Wall of Fire": return "Стіна до 60×20×1 фут або кільце діаметром до 20 футів: при появі Спритність проти 5к8 вогню, успіх — половина. Обраний бік обпікає на 10 футів; вхід у стіну вперше за хід або завершення ходу в ній чи гарячій зоні — 5к8 без ряткидка.";
                case "Gust of Wind": return modern
                    ? "Лінія вітру 60×10 футів: Сила проти відштовхування на 15 футів при появі й наприкінці ходу. Рух назустріч коштує вдвічі більше; розвіює гази й гасить відкритий вогонь. Бонусною дією змінюй напрямок."
                    : "Лінія вітру 60×10 футів: на початку ходу Сила проти відштовхування на 15 футів. Рух назустріч коштує вдвічі більше; розвіює гази й гасить відкритий вогонь. Бонусною дією змінюй напрямок.";
                case "Wall of Stone": return "Створи десять кам’яних панелей 10×10 футів завтовшки 6 дюймів, з’єднаних із наявним каменем. Панель: КО 15, 30 ОЗ на дюйм товщини. Замкнена істота може ряткидком Спритності й реакцією втекти на свою швидкість. Після 10 хвилин концентрації стіна постійна.";
                case "Misty Step": return "Телепортуйся у видиме вільне місце на відстань до 30 футів.";
                case "Suggestion": return modern
                    ? "Істота, що чує й розуміє тебе: Мудрість або Зачарована та виконує досяжну вказівку до 25 слів без очевидної шкоди їй чи союзникам. Завершується після виконання або шкоди цілі від тебе чи союзників."
                    : "Істота, що чує й розуміє тебе: Мудрість або виконує розумну вказівку в одному-двох реченнях без очевидної шкоди собі. Імунітет до зачарування захищає; шкода цілі від тебе чи союзників завершує ефект.";
                case "Invisibility": return modern
                    ? "Охоча істота й речі, які вона носить, стають Невидимими до атаки, завдання шкоди або накладання спела."
                    : "Охоча істота й речі, які вона носить, стають Невидимими до атаки або накладання спела.";
                case "Ray of Enfeeblement": return modern
                    ? "Статура: провал — завада кидків к20, що використовують Силу, й −1к8 до всіх кидків шкоди; наприкінці ходів повторює ряткидок. Успіх — завада наступної атаки до початку твого наступного ходу."
                    : "Дальня атака спелом: влучання змушує ціль завдавати половину шкоди атаками зброєю, які використовують Силу. Наприкінці ходів Статура може завершити ефект.";
                default: return "";
            }
        }
    }
}
